    const ch = (await e.chapters(url)).map(c => ({ name: c.name, url: c.url })).reverse();
    const out = { name: d.name, imageUrl: d.cover, description: d.description, author: d.author, status: d.ongoing ? 0 : 1, genre: d.genres, link: url };
